#include <stdio.h>
#include <stdint.h>

int64_t largestCoin(int64_t cents) {
    if (cents < 1) {
        return 0;
    }

    if (cents >= 100) {
        return 100;
    } else if (cents >= 50) {
        return 50;
    } else if (cents >= 25) {
        return 25;
    } else if (cents >= 10) {
        return 10;
    } else if (cents >= 5) {
        return 5;
    } else {
        return 1;
    }
}

int main(void) {
    int64_t test_cases[] = {0, 1, 4, 5, 9, 10, 24, 25, 49, 50, 99, 100, 125, 250};
    int num_tests = sizeof(test_cases) / sizeof(test_cases[0]);

    for (int i = 0; i < num_tests; i++) {
        printf("%lld\n", (long long)largestCoin(test_cases[i]));
    }

    return 0;
}

