import java.util.*;

public class Solution {
    public static long largestCoin(long cents) {
        if (cents < 1) {
            return 0L;
        }
        long[] denominations = {100L, 50L, 25L, 10L, 5L, 1L};
        for (long denom : denominations) {
            if (cents >= denom) {
                return denom;
            }
        }
        return 0L;
    }

    public static void main(String[] args) {
        System.out.println(largestCoin(250));
        System.out.println(largestCoin(99));
        System.out.println(largestCoin(0));
        System.out.println(largestCoin(1));
        System.out.println(largestCoin(101));
        System.out.println(largestCoin(49));
        System.out.println(largestCoin(1000000));
    }
}
